# ----------------------------------------------------------------
# SESSION STATE
# ----------------------------------------------------------------

def initialize_state() -> None:
    """Create stable session values without overwriting user changes."""
    defaults = {
        "dragon_settings": DEFAULT_SETTINGS.copy(),
        "dragon_selected_tab": "Creature",
        "dragon_show_info": True,
        "dragon_camera_preset": "Front three-quarter",
    }
    for key, value in defaults.items():
        if key not in st.session_state:
            st.session_state[key] = value


initialize_state()


# ----------------------------------------------------------------
# THEME AND PAGE PRESENTATION
# ----------------------------------------------------------------

def inject_theme() -> None:
    """Apply the dark fantasy interface skin."""
    st.markdown(
        """
        <style>
        @import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@500;600;700;800&family=Inter:wght@400;500;600;700&display=swap');

        :root {
            --forge-bg: #050a0a;
            --forge-panel: #0b1514;
            --forge-panel-2: #101f1c;
            --forge-line: rgba(147, 194, 170, .17);
            --forge-text: #e4eee8;
            --forge-muted: #8fa79a;
            --forge-green: #91e0ae;
            --forge-gold: #d5ad69;
        }

        html, body, [data-testid="stAppViewContainer"] {
            background:
                radial-gradient(ellipse at 15% 0%, rgba(45, 106, 79, .20), transparent 34%),
                radial-gradient(ellipse at 90% 20%, rgba(95, 71, 39, .13), transparent 30%),
                linear-gradient(145deg, #050a0a 0%, #08110f 48%, #050909 100%);
            color: var(--forge-text);
            font-family: Inter, sans-serif;
        }

        [data-testid="stHeader"] { background: transparent; }
        [data-testid="stSidebar"] {
            background: linear-gradient(180deg, #0b1714, #07100f);
            border-right: 1px solid var(--forge-line);
        }

        .block-container {
            max-width: 1500px;
            padding-top: 1.4rem;
            padding-bottom: 2rem;
        }

        h1, h2, h3, .forge-title {
            font-family: Cinzel, serif !important;
            letter-spacing: .075em;
        }

        .forge-topline {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 1rem;
            border-bottom: 1px solid var(--forge-line);
            padding: .3rem 0 1rem 0;
            margin-bottom: 1.2rem;
        }

        .forge-brand {
            color: var(--forge-green);
            font-family: Cinzel, serif;
            font-size: .82rem;
            letter-spacing: .24em;
            font-weight: 800;
        }

        .forge-status {
            color: var(--forge-muted);
            font-size: .72rem;
            letter-spacing: .13em;
            text-transform: uppercase;
        }

        .forge-hero {
            padding: 1.25rem 1.45rem;
            border: 1px solid var(--forge-line);
            border-radius: 18px;
            background:
                linear-gradient(120deg, rgba(27, 57, 45, .66), rgba(9, 20, 18, .82)),
                radial-gradient(circle at 85% 10%, rgba(213, 173, 105, .12), transparent 35%);
            box-shadow: 0 18px 55px rgba(0, 0, 0, .23);
            margin-bottom: 1rem;
        }

        .forge-kicker {
            color: var(--forge-gold);
            font-size: .67rem;
            letter-spacing: .24em;
            text-transform: uppercase;
            font-weight: 700;
        }

        .forge-heading {
            color: #edf6ef;
            font-family: Cinzel, serif;
            font-size: clamp(1.5rem, 3vw, 2.35rem);
            font-weight: 800;
            letter-spacing: .08em;
            margin: .25rem 0;
        }

        .forge-subtitle {
            color: #a9beb1;
            font-size: .88rem;
            line-height: 1.55;
            max-width: 780px;
        }

        .forge-panel {
            border: 1px solid var(--forge-line);
            border-radius: 15px;
            background: linear-gradient(155deg, rgba(17, 34, 29, .95), rgba(8, 17, 16, .96));
            padding: 1rem 1.1rem;
            margin-bottom: .85rem;
        }

        .forge-panel-title {
            color: var(--forge-green);
            font-family: Cinzel, serif;
            letter-spacing: .12em;
            font-size: .78rem;
            margin-bottom: .65rem;
        }

        .forge-small {
            color: var(--forge-muted);
            font-size: .75rem;
            line-height: 1.5;
        }

        .forge-chip {
            display: inline-block;
            border: 1px solid rgba(145, 224, 174, .28);
            background: rgba(67, 125, 89, .12);
            color: #b9e8c8;
            border-radius: 999px;
            padding: .28rem .62rem;
            margin: .12rem .2rem .12rem 0;
            font-size: .68rem;
            letter-spacing: .06em;
        }

        div[data-testid="stMetric"] {
            background: rgba(15, 32, 26, .72);
            border: 1px solid var(--forge-line);
            padding: .65rem .8rem;
            border-radius: 12px;
        }

        div[data-testid="stMetricLabel"] { color: var(--forge-muted); }
        div[data-testid="stMetricValue"] { color: #d9f3e1; }

        .stButton > button {
            border: 1px solid rgba(145, 224, 174, .32);
            background: linear-gradient(135deg, #173b2b, #10251e);
            color: #e5f6e9;
            border-radius: 10px;
            font-weight: 600;
            transition: .2s ease;
        }

        .stButton > button:hover {
            border-color: var(--forge-green);
            color: white;
            box-shadow: 0 0 20px rgba(91, 202, 132, .15);
        }

        [data-testid="stSlider"] [role="slider"] {
            background: var(--forge-green);
        }

        .forge-footer {
            border-top: 1px solid var(--forge-line);
            margin-top: 1.3rem;
            padding-top: .8rem;
            color: #71877b;
            font-size: .68rem;
            letter-spacing: .08em;
            text-align: center;
        }
        </style>
        """,
        unsafe_allow_html=True,
    )


inject_theme()


# ----------------------------------------------------------------
# DATA MODELS
# ----------------------------------------------------------------

@dataclass
class CreatureAnatomy:
    """High-level anatomy values shared by all future creature systems."""
    heads: int = 1
    tails: int = 2
    wings: int = 2
    legs: int = 2
    neck_segments: int = 12
    tail_segments: int = 24
    wing_finger_count: int = 5
    body_length: float = 5.8
    neck_length: float = 3.2
    tail_length: float = 5.0
    wing_span: float = 15.0


@dataclass
class SceneConfiguration:
    """Scene configuration passed to the browser-side renderer."""
    scene_id: str = SCENE_ID
    environment: str = "Obsidian Highlands"
    time_of_day: str = "Eclipse"
    fog_density: float = 0.012
    ground_radius: float = 42.0
    camera_distance: float = 18.0


ANATOMY = CreatureAnatomy()
SCENE_CONFIGURATION = SceneConfiguration()


