def build_scene_html(settings: dict[str, Any]) -> str:
    """Build the self-contained Three.js viewport.

    The model is procedural: its body, long neck, narrow head, paired
    tails, two legs, and enormous wings are assembled from meshes.
    Later parts will replace and extend these foundation systems with
    more sophisticated anatomy, scales, claws, facial structures,
    wing membranes, rigging, and animation.
    """
    payload = json.dumps(settings)
    anatomy_payload = json.dumps(asdict(ANATOMY))
    scale_payload = json.dumps(PROCEDURAL_SCALE_LAYOUT)
    scene_payload = json.dumps(asdict(SCENE_CONFIGURATION))

    html = r"""
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<style>
    * { box-sizing: border-box; }
    html, body {
        width: 100%;
        height: 100%;
        margin: 0;
        overflow: hidden;
        background: #050b0b;
        font-family: Inter, Arial, sans-serif;
    }
    #dragon-root {
        position: relative;
        width: 100%;
        height: 690px;
        overflow: hidden;
        border: 1px solid rgba(145,224,174,.22);
        border-radius: 18px;
        background:
            radial-gradient(ellipse at 50% 70%, rgba(47,91,71,.23), transparent 44%),
            linear-gradient(180deg, #101d1b 0%, #0a1313 55%, #050909 100%);
    }
    #dragon-canvas {
        position: absolute;
        inset: 0;
        width: 100%;
        height: 100%;
        display: block;
    }
    #scene-label {
        position: absolute;
        top: 17px;
        left: 19px;
        z-index: 4;
        color: rgba(222,242,228,.83);
        font-size: 10px;
        letter-spacing: .2em;
        text-transform: uppercase;
        pointer-events: none;
    }
    #scene-caption {
        position: absolute;
        bottom: 17px;
        left: 19px;
        z-index: 4;
        color: rgba(183,211,193,.68);
        font-size: 10px;
        letter-spacing: .13em;
        pointer-events: none;
    }
    #hint {
        position: absolute;
        right: 18px;
        bottom: 17px;
        color: rgba(183,211,193,.58);
        font-size: 9px;
        letter-spacing: .1em;
        pointer-events: none;
    }
</style>
</head>
<body>
<div id="dragon-root">
<div id="scene-label">DRAGON FORGE / SPECIMEN 001</div>
    <div id="scene-caption">OBSIDIAN HIGHLANDS · ECLIPSE ENVIRONMENT</div>
    <div id="hint">DRAG TO ORBIT · SCROLL TO ZOOM</div>
    <div id="dragon-error" style="display:none;position:absolute;inset:auto 16px 52px 16px;z-index:10;padding:12px 14px;border:1px solid #b66b55;border-radius:10px;background:#211512;color:#ffd7c9;font:12px/1.5 Arial,sans-serif;white-space:pre-wrap"></div>
    <canvas id="dragon-canvas"></canvas>
</div>

<script type="module">
import * as THREE from "https://esm.sh/three@0.160.0";
import { OrbitControls } from "https://esm.sh/three@0.160.0/examples/jsm/controls/OrbitControls.js";

const SETTINGS = __SETTINGS__;
const ANATOMY = __ANATOMY__;
const SCALE_LAYOUT = __SCALE_LAYOUT__;
const SCENE_CONFIG = __SCENE__;

const errorBox = document.getElementById("dragon-error");
function showDragonError(error) {
    if (!errorBox) return;
    errorBox.style.display = "block";
    errorBox.textContent = "3D VIEWPORT ERROR: " + (error?.message || String(error));
    console.error("Dragon viewport error:", error);
}
window.addEventListener("error", (event) => showDragonError(event.error || event.message));
window.addEventListener("unhandledrejection", (event) => showDragonError(event.reason));

try {
const canvas = document.getElementById("dragon-canvas");
const renderer = new THREE.WebGLRenderer({
    canvas,
    antialias: true,
    alpha: true,
    powerPreference: "high-performance"
});

renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;

const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x0a1714, SCENE_CONFIG.fog_density);

const camera = new THREE.PerspectiveCamera(38, 1, 0.1, 180);
camera.position.set(11, 7.2, 15);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.055;
controls.minDistance = 7;
controls.maxDistance = 42;
controls.target.set(0, 2.2, 0);
controls.maxPolarAngle = Math.PI * 0.49;

const ambient = new THREE.HemisphereLight(0x9fc9b1, 0x101915, 1.35);
scene.add(ambient);

const keyLight = new THREE.DirectionalLight(0xe5f1dc, 3.1);
keyLight.position.set(-7, 13, 8);
keyLight.castShadow = true;
keyLight.shadow.mapSize.set(2048, 2048);
keyLight.shadow.camera.left = -18;
keyLight.shadow.camera.right = 18;
keyLight.shadow.camera.top = 18;
keyLight.shadow.camera.bottom = -18;
scene.add(keyLight);

const rimLight = new THREE.DirectionalLight(0x73c9a0, 2.2);
rimLight.position.set(8, 7, -10);
scene.add(rimLight);

const warmLight = new THREE.PointLight(0xc18b4c, 28, 24, 2);
warmLight.position.set(0, 4, 7);
scene.add(warmLight);

const dragon = new THREE.Group();
dragon.name = "VOID_WYRM_ROOT";
scene.add(dragon);

const materials = {
    body: new THREE.MeshStandardMaterial({
        color: SETTINGS.body_color,
        roughness: 0.73,
        metalness: 0.16
    }),
    underside: new THREE.MeshStandardMaterial({
        color: 0x52675a,
        roughness: 0.82,
        metalness: 0.05
    }),
    wing: new THREE.MeshStandardMaterial({
        color: SETTINGS.wing_color,
        roughness: 0.84,
        side: THREE.DoubleSide
    }),
    membrane: new THREE.MeshStandardMaterial({
        color: SETTINGS.membrane_color,
        roughness: 0.66,
        side: THREE.DoubleSide,
        transparent: true,
        opacity: 0.91
    }),
    horn: new THREE.MeshStandardMaterial({
        color: SETTINGS.horn_color,
        roughness: 0.55
    }),
    eye: new THREE.MeshStandardMaterial({
        color: SETTINGS.eye_color,
        emissive: SETTINGS.eye_color,
        emissiveIntensity: 1.7,
        roughness: 0.25
    }),
    claw: new THREE.MeshStandardMaterial({
        color: 0x171c19,
        roughness: 0.42,
        metalness: 0.24
    })
};

function addMesh(geometry, material, parent, position, rotation) {
    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.set(position.x, position.y, position.z);
    if (rotation) {
        mesh.rotation.set(rotation.x || 0, rotation.y || 0, rotation.z || 0);
    }
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    parent.add(mesh);
    return mesh;
}

function addEllipsoid(parent, position, scale, material, rotation = null) {
    const geometry = new THREE.SphereGeometry(1, 32, 24);
    const mesh = addMesh(geometry, material, parent, position, rotation);
    mesh.scale.set(scale.x, scale.y, scale.z);
    return mesh;
}

function addBone(parent, start, end, radiusStart, radiusEnd, material, radial = 12) {
    const a = new THREE.Vector3(start.x, start.y, start.z);
    const b = new THREE.Vector3(end.x, end.y, end.z);
    const direction = new THREE.Vector3().subVectors(b, a);
    const length = direction.length();
    const geometry = new THREE.CylinderGeometry(
        radiusEnd,
        radiusStart,
        length,
        radial,
        1,
        false
    );
    const mesh = addMesh(
        geometry,
        material,
        parent,
        {
            x: (a.x + b.x) / 2,
            y: (a.y + b.y) / 2,
            z: (a.z + b.z) / 2
        }
    );
    mesh.quaternion.setFromUnitVectors(
        new THREE.Vector3(0, 1, 0),
        direction.normalize()
    );
    return mesh;
}

function addTaperedTail(parent, side, length, segments) {
    const tail = new THREE.Group();
    tail.name = side < 0 ? "LEFT_TAIL" : "RIGHT_TAIL";
    parent.add(tail);

    const points = [];
    for (let i = 0; i <= segments; i++) {
        const t = i / segments;
        points.push(new THREE.Vector3(
            side * 0.28 + Math.sin(t * 4.2) * 0.22,
            1.18 - t * 0.55 + Math.sin(t * 5.0) * 0.16,
            -1.55 - t * length
        ));
    }

    for (let i = 0; i < segments; i++) {
        const p0 = points[i];
        const p1 = points[i + 1];
        const t = i / segments;
        const r0 = 0.27 * (1 - t) + 0.025;
        const r1 = 0.27 * (1 - (i + 1) / segments) + 0.018;
        addBone(
            tail,
            p0,
            p1,
            r0,
            r1,
            materials.body,
            10
        );
    }

    const tip = addEllipsoid(
        tail,
        points[segments],
        { x: 0.09, y: 0.09, z: 0.19 },
        materials.horn
    );
    tip.rotation.x = 0.35;

    return tail;
}

function addLongNeck(parent) {
    const neck = new THREE.Group();
    neck.name = "LONG_SLENDER_NECK";
    parent.add(neck);

    const segments = ANATOMY.neck_segments;
    const start = new THREE.Vector3(0, 2.25, 1.35);
    const finish = new THREE.Vector3(0, 4.25, 3.25);

    for (let i = 0; i < segments; i++) {
        const t0 = i / segments;
        const t1 = (i + 1) / segments;
        const p0 = new THREE.Vector3().lerpVectors(start, finish, t0);
        const p1 = new THREE.Vector3().lerpVectors(start, finish, t1);
        p0.x += Math.sin(t0 * Math.PI) * 0.16;
        p1.x += Math.sin(t1 * Math.PI) * 0.16;

        const radius0 = 0.34 - t0 * 0.15;
        const radius1 = 0.34 - t1 * 0.15;

        addBone(
            neck,
            p0,
            p1,
            radius0,
            radius1,
            materials.body,
            14
        );
    }

    addEllipsoid(
        neck,
        { x: 0, y: 2.75, z: 1.85 },
        { x: 0.29, y: 0.2, z: 0.43 },
        materials.underside,
        { x: -0.55, y: 0, z: 0 }
    );

    return neck;
}

function addSlimHead(parent) {
    const head = new THREE.Group();
    head.name = "SINGLE_SLENDER_DRAGON_HEAD";
    head.position.set(0, 4.23, 3.18);
    parent.add(head);

    addEllipsoid(
        head,
        { x: 0, y: 0, z: 0.12 },
        { x: 0.34, y: 0.31, z: 0.61 },
        materials.body,
        { x: 0.08, y: 0, z: 0 }
    );

    addEllipsoid(
        head,
        { x: 0, y: -0.11, z: 0.65 },
        { x: 0.19, y: 0.16, z: 0.72 },
        materials.body,
        { x: -0.08, y: 0, z: 0 }
    );

    addEllipsoid(
        head,
        { x: 0, y: -0.22, z: 1.15 },
        { x: 0.16, y: 0.095, z: 0.24 },
        materials.underside
    );

    for (const side of [-1, 1]) {
        addEllipsoid(
            head,
            { x: side * 0.285, y: 0.105, z: 0.23 },
            { x: 0.075, y: 0.07, z: 0.13 },
            materials.eye
        );

        addBone(
            head,
            { x: side * 0.18, y: 0.22, z: -0.1 },
            { x: side * 0.38, y: 0.64, z: -0.46 },
            0.105,
            0.008,
            materials.horn,
            10
        );

        addBone(
            head,
            { x: side * 0.12, y: -0.05, z: 1.2 },
            { x: side * 0.12, y: -0.04, z: 1.43 },
            0.045,
            0.012,
            materials.claw,
            8
        );
    }

    return head;
}

function addLeg(parent, side) {
    const leg = new THREE.Group();
    leg.name = side < 0 ? "LEFT_LEG" : "RIGHT_LEG";
    parent.add(leg);

    const hip = { x: side * 0.55, y: 1.55, z: -0.55 };
    const knee = { x: side * 0.67, y: 0.88, z: -0.22 };
    const ankle = { x: side * 0.68, y: 0.19, z: 0.03 };

    addEllipsoid(
        leg,
        hip,
        { x: 0.39, y: 0.53, z: 0.43 },
        materials.body
    );

    addBone(leg, hip, knee, 0.29, 0.19, materials.body, 16);
    addEllipsoid(
        leg,
        knee,
        { x: 0.22, y: 0.23, z: 0.23 },
        materials.body
    );
    addBone(leg, knee, ankle, 0.19, 0.13, materials.body, 14);

    addEllipsoid(
        leg,
        { x: side * 0.68, y: 0.13, z: 0.25 },
        { x: 0.27, y: 0.13, z: 0.42 },
        materials.body
    );

    for (let toe = -1; toe <= 1; toe++) {
        const toeStart = {
            x: side * 0.68 + toe * 0.13,
            y: 0.11,
            z: 0.38
        };
        const toeEnd = {
            x: side * 0.68 + toe * 0.16,
            y: 0.075,
            z: 0.67
        };
        addBone(leg, toeStart, toeEnd, 0.075, 0.035, materials.body, 9);
        addBone(
            leg,
            toeEnd,
            {
                x: toeEnd.x,
                y: toeEnd.y - 0.015,
                z: toeEnd.z + 0.13
            },
            0.04,
            0.004,
            materials.claw,
            8
        );
    }

    return leg;
}

function createWing(side) {
    const wing = new THREE.Group();
    wing.name = side < 0 ? "LEFT_GIGANTIC_WING" : "RIGHT_GIGANTIC_WING";
    wing.position.set(side * 0.48, 2.35, 0.45);
    dragon.add(wing);

    const s = side;
    const root = { x: 0, y: 0, z: 0 };
    const shoulder = { x: s * 1.45, y: 0.62, z: -0.1 };
    const elbow = { x: s * 3.35, y: 1.22, z: -0.55 };
    const wrist = { x: s * 6.1, y: 0.38, z: -0.85 };
    const outerTip = { x: s * 7.25, y: -0.05, z: -1.25 };

    addBone(wing, root, shoulder, 0.31, 0.22, materials.wing, 14);
    addBone(wing, shoulder, elbow, 0.22, 0.14, materials.wing, 12);
    addBone(wing, elbow, wrist, 0.15, 0.075, materials.wing, 10);
    addBone(wing, wrist, outerTip, 0.075, 0.018, materials.wing, 9);

    const fingerEnds = [
        { x: s * 2.3, y: -0.55, z: 1.35 },
        { x: s * 4.0, y: -0.82, z: 0.72 },
        { x: s * 5.6, y: -0.5, z: 0.05 },
        { x: s * 6.7, y: -0.22, z: -0.62 }
    ];

    const fingerStarts = [shoulder, elbow, elbow, wrist];

    for (let i = 0; i < fingerEnds.length; i++) {
        addBone(
            wing,
            fingerStarts[i],
            fingerEnds[i],
            0.085 - i * 0.012,
            0.014,
            materials.wing,
            9
        );
    }

    const membraneVertices = [
        0, 0, 0,
        shoulder.x, shoulder.y, shoulder.z,
        elbow.x, elbow.y, elbow.z,
        wrist.x, wrist.y, wrist.z,
        outerTip.x, outerTip.y, outerTip.z,
        fingerEnds[0].x, fingerEnds[0].y, fingerEnds[0].z,
        fingerEnds[1].x, fingerEnds[1].y, fingerEnds[1].z,
        fingerEnds[2].x, fingerEnds[2].y, fingerEnds[2].z,
        fingerEnds[3].x, fingerEnds[3].y, fingerEnds[3].z
    ];

    const membraneIndices = [
        0, 1, 5,
        1, 2, 5,
        2, 6, 5,
        2, 3, 6,
        3, 7, 6,
        3, 4, 7,
        4, 8, 7
    ];

    const membraneGeometry = new THREE.BufferGeometry();
    membraneGeometry.setAttribute(
        "position",
        new THREE.Float32BufferAttribute(membraneVertices, 3)
    );
    membraneGeometry.setIndex(membraneIndices);
    membraneGeometry.computeVertexNormals();

    const membrane = new THREE.Mesh(membraneGeometry, materials.membrane);
    membrane.castShadow = true;
    membrane.receiveShadow = true;
    wing.add(membrane);

    return wing;
}

function createTorso() {
    const torso = new THREE.Group();
    torso.name = "ELONGATED_SLIM_TORSO";
    dragon.add(torso);

    addEllipsoid(
        torso,
        { x: 0, y: 1.78, z: 0 },
        { x: 0.82, y: 0.72, z: 1.75 },
        materials.body
    );

    addEllipsoid(
        torso,
        { x: 0, y: 1.36, z: 0.05 },
        { x: 0.63, y: 0.28, z: 1.4 },
        materials.underside
    );

    addEllipsoid(
        torso,
        { x: 0, y: 2.12, z: -0.82 },
        { x: 0.72, y: 0.56, z: 0.88 },
        materials.body
    );

    return torso;
}

function createSpineDetails() {
    const spine = new THREE.Group();
    spine.name = "DORSAL_SPINE_DETAILS";
    dragon.add(spine);

    const count = 18;
    for (let i = 0; i < count; i++) {
        const t = i / (count - 1);
        const z = 1.15 - t * 3.15;
        const y = 2.28 - Math.abs(t - 0.45) * 0.18;
        const height = 0.16 + Math.sin(t * Math.PI) * 0.19;

        addBone(
            spine,
            { x: 0, y, z },
            { x: 0, y: y + height, z: z - 0.08 },
            0.11 * (1 - t * 0.35),
            0.006,
            materials.horn,
            7
        );
    }
    return spine;
}

function createGround() {
    const groundMaterial = new THREE.MeshStandardMaterial({
        color: 0x111d19,
        roughness: 0.96,
        metalness: 0.02
    });

    const ground = new THREE.Mesh(
        new THREE.CircleGeometry(SCENE_CONFIG.ground_radius, 96),
        groundMaterial
    );
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.035;
    ground.receiveShadow = true;
    scene.add(ground);

    if (SETTINGS.show_grid) {
        const grid = new THREE.GridHelper(80, 80, 0x456b56, 0x203a2e);
        grid.position.y = -0.02;
        scene.add(grid);
    }

    if (SETTINGS.show_ground) {
        const ringMaterial = new THREE.MeshBasicMaterial({
            color: 0x355746,
            transparent: true,
            opacity: 0.22
        });
        const ring = new THREE.Mesh(
            new THREE.RingGeometry(10.5, 10.58, 96),
            ringMaterial
        );
        ring.rotation.x = -Math.PI / 2;
        ring.position.y = 0.002;
        scene.add(ring);
    }
}

function createAtmosphere() {
    const starGeometry = new THREE.BufferGeometry();
    const starPositions = [];
    for (let i = 0; i < 420; i++) {
        const radius = 22 + Math.random() * 42;
        const theta = Math.random() * Math.PI * 2;
        const phi = Math.random() * Math.PI;
        starPositions.push(
            radius * Math.sin(phi) * Math.cos(theta),
            radius * Math.cos(phi) + 9,
            radius * Math.sin(phi) * Math.sin(theta)
        );
    }
    starGeometry.setAttribute(
        "position",
        new THREE.Float32BufferAttribute(starPositions, 3)
    );

    const stars = new THREE.Points(
        starGeometry,
        new THREE.PointsMaterial({
            color: 0xb9d9c3,
            size: 0.075,
            transparent: true,
            opacity: 0.68
        })
    );
    scene.add(stars);
}


function createMicroScaleLayer() {
    const geometry = new THREE.IcosahedronGeometry(0.052, 0);
    const material = new THREE.MeshStandardMaterial({
        color: 0x759783,
        roughness: 0.58,
        metalness: 0.12
    });
    const instance = new THREE.InstancedMesh(geometry, material, SCALE_LAYOUT.length);
    instance.name = "NINETEEN_THOUSAND_PROCEDURAL_SCALE_DETAILS";
    instance.castShadow = true;
    instance.receiveShadow = true;
    const dummy = new THREE.Object3D();
    const color = new THREE.Color();

    SCALE_LAYOUT.forEach((record, index) => {
        const [region, x, y, z, size, rotation] = record;
        dummy.position.set(x, y, z);
        dummy.rotation.set(rotation * 0.12, rotation, rotation * 0.08);
        dummy.scale.set(size * 1.8, size * 0.65, size * 1.25);
        dummy.updateMatrix();
        instance.setMatrixAt(index, dummy.matrix);
        const shade = 0.72 + ((index * 37) % 29) / 100;
        color.setRGB(0.34 * shade, 0.52 * shade, 0.40 * shade);
        instance.setColorAt(index, color);
    });

    instance.instanceMatrix.needsUpdate = true;
    if (instance.instanceColor) instance.instanceColor.needsUpdate = true;
    dragon.add(instance);
    return instance;
}


function assembleDragon() {
    createTorso();
    addLongNeck(dragon);
    addSlimHead(dragon);
    addTaperedTail(dragon, -1, ANATOMY.tail_length, ANATOMY.tail_segments);
    addTaperedTail(dragon, 1, ANATOMY.tail_length * 1.08, ANATOMY.tail_segments);
    addLeg(dragon, -1);
    addLeg(dragon, 1);
    createWing(-1);
    createWing(1);
    createSpineDetails();
    createMicroScaleLayer();
}

assembleDragon();
createGround();
createAtmosphere();

const clock = new THREE.Clock();
const animatedParts = dragon.children.filter((child) =>
    child.name.includes("WING")
);

function resizeRenderer() {
    const width = canvas.clientWidth;
    const height = canvas.clientHeight;
    if (!width || !height) return;

    renderer.setSize(width, height, false);
    camera.aspect = width / height;
    camera.updateProjectionMatrix();
}

window.addEventListener("resize", resizeRenderer);
resizeRenderer();

function animate() {
    requestAnimationFrame(animate);
    const elapsed = clock.getElapsedTime();

    if (SETTINGS.animation) {
        dragon.position.y = Math.sin(elapsed * 1.15) * 0.045;
        dragon.rotation.y = Math.sin(elapsed * 0.22) * 0.035;

        animatedParts.forEach((wing, index) => {
            const direction = index === 0 ? -1 : 1;
            wing.rotation.z = direction * (
                0.035 + Math.sin(elapsed * 1.7 + index * Math.PI) * 0.055
            );
        });
    }

    controls.update();
    renderer.render(scene, camera);
}

animate();
} catch (error) {
    showDragonError(error);
}
</script>
</body>
</html>
"""

    html = html.replace("__SETTINGS__", payload)
    html = html.replace("__ANATOMY__", anatomy_payload)
    html = html.replace("__SCALE_LAYOUT__", scale_payload)
    html = html.replace("__SCENE__", scene_payload)
    return html


