def render_sidebar() -> dict[str, Any]:
    """Render adjustable creature parameters."""
    st.sidebar.markdown("## 🐉 DRAGON FORGE")
    st.sidebar.caption("ANCIENT CREATURE WORKSHOP")
    st.sidebar.markdown("---")

    settings = st.session_state.dragon_settings

    st.sidebar.markdown("### Creature proportions")
    settings["wing_span"] = st.sidebar.slider(
        "Wing scale", 0.65, 1.45, float(settings["wing_span"]), 0.05
    )
    settings["neck_length"] = st.sidebar.slider(
        "Neck length", 0.70, 1.45, float(settings["neck_length"]), 0.05
    )
    settings["tail_length"] = st.sidebar.slider(
        "Tail length", 0.70, 1.50, float(settings["tail_length"]), 0.05
    )
    settings["body_build"] = st.sidebar.slider(
        "Body build", 0.60, 1.20, float(settings["body_build"]), 0.05
    )

    st.sidebar.markdown("---")
    st.sidebar.markdown("### Appearance")
    settings["body_color"] = st.sidebar.color_picker(
        "Scale / body color", settings["body_color"]
    )
    settings["wing_color"] = st.sidebar.color_picker(
        "Wing bone color", settings["wing_color"]
    )
    settings["membrane_color"] = st.sidebar.color_picker(
        "Wing membrane", settings["membrane_color"]
    )
    settings["eye_color"] = st.sidebar.color_picker(
        "Eye glow", settings["eye_color"]
    )
    settings["horn_color"] = st.sidebar.color_picker(
        "Horn color", settings["horn_color"]
    )

    st.sidebar.markdown("---")
    st.sidebar.markdown("### Scene options")
    settings["animation"] = st.sidebar.toggle(
        "Idle animation", value=bool(settings["animation"])
    )
    settings["show_ground"] = st.sidebar.toggle(
        "Ground ring", value=bool(settings["show_ground"])
    )
    settings["show_grid"] = st.sidebar.toggle(
        "Technical grid", value=bool(settings["show_grid"])
    )

    if st.sidebar.button("Reset creature settings", use_container_width=True):
        st.session_state.dragon_settings = DEFAULT_SETTINGS.copy()
        st.rerun()

    st.session_state.dragon_settings = settings
    return settings


